<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Creator Workspace - Collapsed Sidebar</title>
    <style>
        :root {
            --bg-app: #0f1115;
            --bg-sidebar: #161920;
            --bg-panel: #1a1e26;
            --bg-input: #252a35;
            --border-color: #2d333f;
            --text-primary: #ffffff;
            --text-secondary: #94a3b8;
            --accent-blue: #38bdf8;
            --accent-green: #10b981;
            --icon-rail-width: 64px;
            --header-height: 56px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        body {
            background-color: var(--bg-app);
            color: var(--text-primary);
            height: 100vh;
            width: 100vw;
            overflow: hidden;
            display: flex;
            flex-direction: column;
        }

        /* --- Header --- */
        header {
            height: var(--header-height);
            background-color: #13161c;
            border-bottom: 1px solid var(--border-color);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 16px;
            flex-shrink: 0;
            z-index: 10;
        }

        .header-left {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .back-btn {
            background: none;
            border: none;
            color: var(--text-secondary);
            cursor: pointer;
            font-size: 14px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .header-title-group {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .project-name {
            font-weight: 600;
            font-size: 15px;
        }

        .status-badge {
            background-color: rgba(16, 185, 129, 0.15);
            color: var(--accent-green);
            border: 1px solid rgba(16, 185, 129, 0.3);
            padding: 2px 8px;
            border-radius: 4px;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.5px;
        }

        .version-info {
            color: var(--text-secondary);
            font-size: 13px;
        }

        .header-right {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .btn {
            padding: 6px 16px;
            border-radius: 6px;
            font-size: 13px;
            font-weight: 500;
            cursor: pointer;
            border: 1px solid transparent;
            transition: all 0.2s;
        }

        .btn-outline {
            background: transparent;
            border-color: var(--border-color);
            color: var(--text-primary);
        }

        .btn-outline:hover {
            background-color: rgba(255,255,255,0.05);
        }

        .btn-primary {
            background-color: var(--accent-blue);
            color: #000;
            border-color: var(--accent-blue);
        }

        .btn-primary:hover {
            filter: brightness(1.1);
        }

        /* --- Main Layout --- */
        .workspace-container {
            display: flex;
            flex: 1;
            overflow: hidden;
        }

        /* --- Left Icon Rail (Collapsed) --- */
        .sidebar-rail {
            width: var(--icon-rail-width);
            background-color: var(--bg-sidebar);
            border-right: 1px solid var(--border-color);
            display: flex;
            flex-direction: column;
            align-items: center;
            padding-top: 12px;
            flex-shrink: 0; /* Fixed narrow width */
        }

        .rail-logo {
            width: 32px;
            height: 32px;
            margin-bottom: 24px;
            color: var(--accent-blue);
        }

        .nav-item {
            width: 40px;
            height: 40px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--text-secondary);
            border-radius: 8px;
            margin-bottom: 8px;
            cursor: pointer;
            transition: background 0.2s, color 0.2s;
        }

        .nav-item:hover {
            background-color: rgba(255,255,255,0.05);
            color: var(--text-primary);
        }

        .nav-item.active {
            background-color: rgba(56, 189, 248, 0.1);
            color: var(--accent-blue);
        }

        .nav-spacer {
            flex: 1;
        }

        .user-avatar {
            width: 32px;
            height: 32px;
            background-color: #3b82f6;
            color: white;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            font-weight: 600;
            margin-bottom: 12px;
            cursor: pointer;
        }

        /* --- Center Content Area (Wider) --- */
        .main-content {
            flex: 1;
            display: flex;
            flex-direction: column;
            min-width: 0; /* Prevents flex overflow */
            background-color: var(--bg-app);
        }

        /* Top Bar inside Main Content */
        .content-header {
            padding: 12px 20px;
            border-bottom: 1px solid var(--border-color);
            display: flex;
            align-items: center;
            justify-content: space-between;
            background-color: #151921;
        }

        .section-title {
            font-weight: 600;
            font-size: 14px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .live-dot {
            width: 8px;
            height: 8px;
            background-color: var(--accent-green);
            border-radius: 50%;
            box-shadow: 0 0 6px var(--accent-green);
        }

        .controls-group {
            display: flex;
            gap: 8px;
        }

        .control-chip {
            background: #252a35;
            border: 1px solid var(--border-color);
            padding: 4px 12px;
            border-radius: 4px;
            font-size: 12px;
            color: var(--text-secondary);
            cursor: pointer;
        }

        .control-chip.active {
            background: #374151;
            color: white;
            border-color: #4b5563;
        }

        /* Scrollable Content Body */
        .content-body {
            flex: 1;
            overflow-y: auto;
            position: relative;
            display: flex;
            flex-direction: column;
        }

        .agent-prompt-area {
            padding: 20px;
            color: var(--text-secondary);
            font-size: 13px;
            line-height: 1.5;
            text-align: center;
            max-width: 400px;
            margin: 0 auto;
        }

        .theme-label {
            position: absolute;
            top: 20px;
            left: 20px;
            font-size: 13px;
            color: var(--text-secondary);
        }

        /* Game Canvas Simulation */
        .canvas-container {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            position: relative;
            background: radial-gradient(circle at center, #1a1f29 0%, #0f1115 100%);
            margin: 20px;
            border-radius: 12px;
            border: 1px solid #232830;
            min-height: 300px;
        }

        .game-ui-element {
            position: absolute;
            top: 20px;
            right: 20px;
            color: #ef4444;
            opacity: 0.6;
            font-size: 20px;
            letter-spacing: 4px;
        }

        .play-button-large {
            width: 80px;
            height: 80px;
            background: linear-gradient(135deg, #60a5fa, #8b5cf6);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            box-shadow: 0 10px 25px rgba(0,0,0,0.5);
            transition: transform 0.2s;
            margin-bottom: 24px;
        }

        .play-button-large:hover {
            transform: scale(1.05);
        }

        .play-icon {
            width: 0; 
            height: 0; 
            border-top: 15px solid transparent;
            border-bottom: 15px solid transparent;
            border-left: 24px solid white;
            margin-left: 6px;
        }

        .canvas-hint {
            color: var(--text-primary);
            font-size: 14px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        /* --- Right Panel --- */
        .right-panel {
            width: 300px;
            background-color: var(--bg-panel);
            border-left: 1px solid var(--border-color);
            display: flex;
            flex-direction: column;
            flex-shrink: 0;
            overflow-y: auto;
        }

        .panel-header {
            padding: 16px;
            font-weight: 600;
            font-size: 14px;
            border-bottom: 1px solid var(--border-color);
        }

        .panel-subheader {
            padding: 12px 16px;
            font-size: 12px;
            color: var(--text-secondary);
            line-height: 1.4;
            border-bottom: 1px solid var(--border-color);
        }

        .settings-list {
            padding: 8px 0;
        }

        .setting-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 10px 16px;
            font-size: 13px;
        }

        .setting-label {
            color: #d1d5db;
        }

        .color-swatch-container {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .color-swatch {
            width: 32px;
            height: 18px;
            border-radius: 3px;
            border: 1px solid rgba(255,255,255,0.1);
        }

        .hex-code {
            font-family: monospace;
            font-size: 11px;
            color: var(--text-secondary);
        }

        .slider-container {
            flex: 1;
            margin-left: 12px;
            display: flex;
            flex-direction: column;
            gap: 4px;
        }

        .slider-track {
            width: 100%;
            height: 4px;
            background: #374151;
            border-radius: 2px;
            position: relative;
        }

        .slider-fill {
            position: absolute;
            left: 0;
            top: 0;
            height: 100%;
            background: var(--accent-blue);
            border-radius: 2px;
        }

        .slider-thumb {
            width: 12px;
            height: 12px;
            background: var(--accent-blue);
            border-radius: 50%;
            position: absolute;
            top: 50%;
            transform: translate(-50%, -50%);
            box-shadow: 0 0 4px rgba(56, 189, 248, 0.5);
        }

        .slider-value {
            text-align: right;
            font-size: 12px;
            color: var(--text-primary);
            font-weight: 500;
        }

        .input-field {
            width: 100%;
            background: var(--bg-input);
            border: 1px solid var(--border-color);
            color: white;
            padding: 8px 12px;
            border-radius: 6px;
            font-size: 13px;
            outline: none;
        }

        .input-field:focus {
            border-color: var(--accent-blue);
        }

        .scene-item {
            display: flex;
            justify-content: space-between;
            padding: 10px 16px;
            font-size: 13px;
            border-top: 1px solid var(--border-color);
            color: #d1d5db;
        }

        .scene-meta {
            font-size: 11px;
            color: var(--text-secondary);
        }

        /* SVG Icons */
        svg {
            fill: currentColor;
            width: 20px;
            height: 20px;
        }
    </style>
</head>
